// Some portions generated by Claude

// Plan task M14.3 (user request): every settings pane opens over the page. Opening one moves nothing (its card and
// the content after it keep their boxes), the pane is on top of what it covers and inside the viewport, and it
// closes with Escape (focus returns to its toggle) and with a press outside it.
// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	runQuery,
	serverBaseUrl,
	setQueryEditor,
	uniqueRepositoryId,
	waitForRoute
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-settings-panes');
const PRODUCT = '<http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/vocabulary/Product>';

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

const QUERY = 'SELECT * WHERE { ?s ?p ?o } LIMIT 3';

/** Explain the query and wait for the explanation, so that nothing is still arriving while the pane is measured. */
async function explain(page) {
	await setQueryEditor(page, QUERY);
	await page.locator('#explain-trigger').click();
	await page.waitForFunction(() => {
		const explanation = document.getElementById('query-explanation');
		return explanation && explanation.textContent.trim().length > 0;
	});
}

const PANES = [
	{ name: 'Query settings', view: 'query', toggle: '#query-options-toggle' },
	{ name: 'Save query', view: 'query', toggle: '#save-query-toggle' },
	{ name: 'result Display', view: 'query', toggle: '.query-result-options-toggle',
		prepare: (page) => runQuery(page, QUERY) },
	{ name: 'result Download', view: 'query', toggle: '.query-result-download-toggle',
		prepare: (page) => runQuery(page, QUERY) },
	{ name: 'explanation Config', view: 'query', toggle: '#explanation-settings-toggle', prepare: explain },
	{ name: 'Explore Display', view: 'explore', search: `?resource=${encodeURIComponent(PRODUCT)}`,
		toggle: '#explore-result-options-toggle' },
	{ name: 'Export advanced settings', view: 'export', toggle: '#export-advanced-toggle' },
	{ name: 'Add advanced settings', view: 'add', toggle: '#add-import-settings-toggle' },
	{ name: 'Server advanced settings', view: 'server', repository: 'NONE', toggle: '#server-auth-toggle' },
	{ name: 'Create advanced settings', view: 'create', repository: 'NONE', search: '?type=native',
		toggle: '#create-advanced-toggle' }
];

/** The boxes that must not move: the toggle, its card and the element after the card. */
function layoutOf(page, toggle) {
	return page.locator(toggle).first().evaluate((element) => {
		const box = (node) => {
			if (!node || node.getClientRects().length === 0) {
				return null;
			}
			const rect = node.getBoundingClientRect();
			return [rect.x, rect.y + window.scrollY, rect.width, rect.height].map((value) => Math.round(value));
		};
		const card = element.closest('.workbench-island, .workbench-form-card, .query-output, .workbench-page-surface');
		return { toggle: box(element), card: box(card), next: box(card && card.nextElementSibling) };
	});
}

/** The layout once it has stopped changing (results and explanations render in steps). */
async function settledLayout(page, toggle) {
	let previous = '';
	await expect.poll(async () => {
		const current = JSON.stringify(await layoutOf(page, toggle));
		const settled = current === previous;
		previous = current;
		return settled;
	}, { intervals: [250], timeout: 10000 }).toBe(true);
	return JSON.parse(previous);
}

for (const viewport of [{ width: 1440, height: 900 }, { width: 390, height: 844 }]) {
	test.describe(`${viewport.width} px`, () => {
		test.use({ viewport, reducedMotion: 'reduce' });

		test('opening one pane closes the pane open beside it', async ({ page }) => {
			await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'));
			await waitForRoute(page, 'query');
			await page.locator('#query-options-toggle').click();
			await expect(page.locator('#query-options-panel')).toBeVisible();

			await page.locator('#save-query-toggle').click();

			await expect(page.locator('#save-query-panel')).toBeVisible();
			await expect(page.locator('#query-options-panel')).toBeHidden();
			await page.locator('#query-options-toggle').click();
			await expect(page.locator('#query-options-panel')).toBeVisible();
			await expect(page.locator('#save-query-panel')).toBeHidden();
		});

		test('a pane opened with a click closes with Escape', async ({ page }) => {
			// WebKit does not focus a button that is clicked, so focus is not on the toggle when Escape is pressed.
			await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'));
			await waitForRoute(page, 'query');
			await page.locator('#query-options-toggle').click();
			await expect(page.locator('#query-options-panel')).toBeVisible();

			await page.keyboard.press('Escape');

			await expect(page.locator('#query-options-panel')).toBeHidden();
			await expect(page.locator('#query-options-toggle')).toHaveAttribute('aria-expanded', 'false');
		});

		for (const pane of PANES) {
			test(`${pane.name} opens over the page and closes with Escape or a press outside it`, async ({ page, browserName }) => {
				const repository = pane.repository || REPOSITORY_ID;
				await page.goto(repositoryPageUrl(repository, pane.view) + (pane.search || ''));
				await waitForRoute(page, pane.view);
				if (pane.prepare) {
					await pane.prepare(page);
				}
				const toggle = page.locator(pane.toggle).first();
				await expect(toggle).toBeVisible({ timeout: 15000 });
				await toggle.scrollIntoViewIfNeeded();
				const panel = page.locator(`#${await toggle.getAttribute('aria-controls')}`);
				const before = await settledLayout(page, pane.toggle);

				await toggle.click();
				await expect(panel).toBeVisible();
				await expect(toggle).toHaveAttribute('aria-expanded', 'true');

				expect(await layoutOf(page, pane.toggle), 'opening the pane moves nothing').toEqual(before);
				const placement = await panel.evaluate((element, toggleSelector) => {
					const rect = element.getBoundingClientRect();
					const button = document.querySelector(toggleSelector);
					// A pane in a toolbar opens below the whole toolbar, so it covers none of the toolbar's buttons.
					const toolbar = button.closest('.workbench-action-toolbar') || button;
					const covered = Array.from(toolbar.querySelectorAll('button, input[type="submit"]')).filter((other) => {
						const box = other.getBoundingClientRect();
						const x = box.left + box.width / 2;
						const y = box.top + box.height / 2;
						return !element.contains(other) && box.width > 0
							&& x > rect.left && x < rect.right && y > rect.top && y < rect.bottom;
					}).map((other) => other.id || other.textContent.trim());
					const inside = (x, y) => element.contains(document.elementFromPoint(x, y));
					const bottom = Math.min(rect.bottom, window.innerHeight) - 4;
					return {
						covered,
						top: Math.round(rect.top - toolbar.getBoundingClientRect().bottom),
						left: rect.left,
						right: rect.right,
						viewport: document.documentElement.clientWidth,
						onTop: [[rect.left + rect.width / 2, (rect.top + bottom) / 2], [rect.left + 4, bottom],
							[rect.right - 4, rect.top + 4]].every(([x, y]) => inside(x, y))
					};
				}, pane.toggle);
				expect(placement.covered, 'the pane covers none of its toolbar\'s buttons').toEqual([]);
				expect(placement.top, 'the pane opens just below its toggle').toBeGreaterThanOrEqual(0);
				expect(placement.top).toBeLessThanOrEqual(12);
				expect(placement.left, 'inside the viewport').toBeGreaterThanOrEqual(0);
				expect(placement.right, 'inside the viewport').toBeLessThanOrEqual(placement.viewport);
				expect(placement.onTop, 'on top of what it covers').toBe(true);

				// The pane follows its toggle, so Tab from the open pane's toggle moves into the pane. Safari's Tab reaches
				// only text fields and pop-up menus, and some panes have neither; Option-Tab reaches every control.
				await toggle.press(browserName === 'webkit' ? 'Alt+Tab' : 'Tab');
				expect(await panel.evaluate((element) => element.contains(document.activeElement)),
					'Tab from the toggle moves into the pane').toBe(true);

				await panel.locator('input, select, button').first().focus();
				await page.keyboard.press('Escape');
				await expect(panel).toBeHidden();
				await expect(toggle).toHaveAttribute('aria-expanded', 'false');
				await expect(toggle).toBeFocused();

				await toggle.click();
				await expect(panel).toBeVisible();
				await page.locator('#workbench-outlet h1').first().click();
				await expect(panel).toBeHidden();
				expect(await layoutOf(page, pane.toggle), 'closing it moves nothing either').toEqual(before);
			});
		}
	});
}

